window.products.push({"id":176043,"name":"Lavish Home Ornate Vine Indoor/Outdoor Area Rug, 5' x 7'7\", Black","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/A13maRL-r4L._AC_SL1500_.jpg","description":"Lavish Home brings you form and function with the Ornate Vine Indoor/Outdoor Area Rug. This stylish rug is water repellent, making it perfect for any backyard, patio, deck or pool side. Great solution for those with kids or pets who need an easy to clean indoor rug. Turn your outdoor space into a comfortable oasis.. Pile Height - 0.1 inches","images":["https://m.media-amazon.com/images/I/A13maRL-r4L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Lavish Home","source_asin":"B016S9U9YI","category_path":"Home & Kitchen"},"sku":"BM-176043","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B016S9U9YI","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B016S9U9YI","price_pending":true,"merchant_ready":false});
